export type ParsedCommitAndSwapInstruction<
  TProgram extends string = typeof CONVENANT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    covenant: TAccountMetas[1];
    /**
     * The escrow vault and the token accounts below are **base-layer only**.
     * They are not delegated to the ER, so passing them as writable accounts
     * on an ER transaction fails with `InvalidWritableAccount`. This
     * instruction only needs their addresses — it builds the Magic Action's
     * account list and schedules it; `swap_on_l1` is what actually touches
     * them, and that runs on the base layer where they are writable.
     */
    vault: TAccountMetas[2];
    /**
     * read here to build the action's account list; the action itself
     * constrains the payout.
     */
    creator: TAccountMetas[3];
    counterparty: TAccountMetas[4];
    creatorVaultAta: TAccountMetas[5];
    counterpartyVaultAta: TAccountMetas[6];
    creatorPayoutAta: TAccountMetas[7];
    counterpartyPayoutAta: TAccountMetas[8];
    creatorMintAcct: TAccountMetas[9];
    counterpartyMintAcct: TAccountMetas[10];
    tokenProgram: TAccountMetas[11];
    systemProgram: TAccountMetas[12];
    magicProgram: TAccountMetas[13];
    magicContext: TAccountMetas[14];
  };
  data: CommitAndSwapInstructionData;
};

export function parseCommitAndSwapInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCommitAndSwapInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      covenant: getNextAccount(),
      vault: getNextAccount(),
      creator: getNextAccount(),
      counterparty: getNextAccount(),
      creatorVaultAta: getNextAccount(),
      counterpartyVaultAta: getNextAccount(),
      creatorPayoutAta: getNextAccount(),
      counterpartyPayoutAta: getNextAccount(),
      creatorMintAcct: getNextAccount(),
      counterpartyMintAcct: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      magicProgram: getNextAccount(),
      magicContext: getNextAccount(),
    },
    data: getCommitAndSwapInstructionDataDecoder().decode(instruction.data),
  };
}
